export type FairOpenPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function fairOpenProgram(
  config: { programAddress?: Address | HasAddress } = {},
) {
  return <T extends FairOpenPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { fairOpen: FairOpenPlugin }> => {
    return extendClient(client, {
      fairOpen: <FairOpenPlugin>{
        accounts: {
          launch: addSelfFetchFunctions(client, getLaunchCodec()),
          programConfig: addSelfFetchFunctions(client, getProgramConfigCodec()),
          seat: addSelfFetchFunctions(client, getSeatCodec()),
          vault: addSelfFetchFunctions(client, getVaultCodec()),
        },
        instructions: {
          closeLaunch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseLaunchInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          createLaunch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateLaunchInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          deposit: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          initialize: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          markFailed: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMarkFailedInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          updateProgramConfig: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateProgramConfigInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          withdraw: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          withdrawFailed: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawFailedInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
        },
        pdas: {
          vault: (seeds, pdaConfig) =>
            findVaultPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          programConfig: (pdaConfig) =>
            findProgramConfigPda({
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          launch: (seeds, pdaConfig) =>
            findLaunchPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
        },
        identifyAccount: identifyFairOpenAccount,
        identifyInstruction: identifyFairOpenInstruction,
        parseInstruction: parseFairOpenInstruction,
      },
    });
  };
}

